async fn test_serialize_deserialize_with_schema() -> anyhow::Result<()> {
    let mut conn = SqliteConnection::connect("sqlite::memory:").await?;

    sqlx::raw_sql(
        "attach ':memory:' as foo; create table foo.foo(bar integer not null, baz text not null)",
    )
