    let rows = sqlx::query_as::<_, (i32, String)>("select bar, baz from foo.foo")
        .fetch_all(&mut conn)
        .await?;

    assert_eq!(rows.len(), 2);

    assert_eq!(rows[0].0, 1234);
    assert_eq!(rows[0].1, "Lorem ipsum");

    assert_eq!(rows[1].0, 5678);
    assert_eq!(rows[1].1, "dolor sit amet");

    Ok(())
}

